// A local simulation of AWS DataStore so the app works without config
let db = [];

export const DataStore = {
    query: async (model, predicate) => {
        // Return dummy data if empty
        if (db.length === 0) {
            return [];
        }
        return db;
    },
    save: async (item) => {
        console.log("💾 [Gemini DB] Saving:", item);
        db.push(item);
        return item;
    },
    observe: () => {
        return {
            subscribe: (cb) => {
                return { unsubscribe: () => {} };
            }
        };
    }
};
